import SwiftUI
import UIKit

@main
struct LiquidGlassApp: App {
    var body: some Scene {
        WindowGroup {
            RootView()
        }
    }
}

struct RootView: View {
    var body: some View {
        Group {
            if #available(iOS 26.0, *) {
                LiquidGlassScreen()
            } else {
                VStack(spacing: 12) {
                    Text("Requires iOS 26 or later")
                        .font(.title3.weight(.semibold))
                    Text("This build uses Liquid Glass APIs that are available starting with iOS 26.")
                        .font(.body)
                        .foregroundStyle(.secondary)
                        .multilineTextAlignment(.center)
                }
                .padding(24)
            }
        }
    }
}

@available(iOS 26.0, *)
struct LiquidGlassScreen: View {
    private let actions: [GlassAction] = [
        .init(id: "play", title: "Play", systemImage: "play.fill"),
        .init(id: "pause", title: "Pause", systemImage: "pause.fill"),
        .init(id: "stop", title: "Stop", systemImage: "stop.fill")
    ]

    var body: some View {
        ZStack {
            LinearGradient(
                colors: [
                    Color(red: 0.09, green: 0.12, blue: 0.20),
                    Color(red: 0.16, green: 0.27, blue: 0.42),
                    Color(red: 0.31, green: 0.46, blue: 0.67)
                ],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
            .ignoresSafeArea()

            ScrollView(showsIndicators: false) {
                VStack(alignment: .leading, spacing: 24) {
                    UIKitGlassCard()
                        .frame(height: 180)

                    Text("Hello")
                        .font(.headline)
                        .padding(.horizontal, 20)
                        .padding(.vertical, 14)
                        .glassEffect(.regular.interactive(), in: .capsule)

                    GlassEffectContainer(spacing: 18) {
                        HStack(spacing: 18) {
                            ForEach(actions) { action in
                                Label(action.title, systemImage: action.systemImage)
                                    .font(.subheadline.weight(.semibold))
                                    .padding(.horizontal, 18)
                                    .padding(.vertical, 14)
                                    .glassEffect(.regular.interactive(), in: .capsule)
                            }
                        }
                    }
                }
                .padding(24)
                .frame(maxWidth: .infinity, alignment: .topLeading)
            }
        }
    }
}

@available(iOS 26.0, *)
struct UIKitGlassCard: UIViewRepresentable {
    func makeUIView(context: Context) -> UIKitGlassCardView {
        UIKitGlassCardView()
    }

    func updateUIView(_ uiView: UIKitGlassCardView, context: Context) {
    }
}

@available(iOS 26.0, *)
final class UIKitGlassCardView: UIView {
    private let visualEffectView: UIVisualEffectView = {
        let glassEffect = UIGlassEffect()
        glassEffect.isInteractive = true
        let view = UIVisualEffectView(effect: glassEffect)
        view.translatesAutoresizingMaskIntoConstraints = false
        view.clipsToBounds = true
        view.layer.cornerRadius = 20
        view.layer.cornerCurve = .continuous
        return view
    }()

    private let titleLabel: UILabel = {
        let label = UILabel()
        label.translatesAutoresizingMaskIntoConstraints = false
        label.text = "UIKit Liquid Glass"
        label.font = .preferredFont(forTextStyle: .title2)
        label.textColor = .label
        label.numberOfLines = 1
        return label
    }()

    private let subtitleLabel: UILabel = {
        let label = UILabel()
        label.translatesAutoresizingMaskIntoConstraints = false
        label.text = "Interactive glass effect rendered inside a single production-ready view."
        label.font = .preferredFont(forTextStyle: .body)
        label.textColor = .secondaryLabel
        label.numberOfLines = 0
        return label
    }()

    override init(frame: CGRect) {
        super.init(frame: frame)
        backgroundColor = .clear
        addSubview(visualEffectView)
        visualEffectView.contentView.addSubview(titleLabel)
        visualEffectView.contentView.addSubview(subtitleLabel)

        NSLayoutConstraint.activate([
            visualEffectView.leadingAnchor.constraint(equalTo: leadingAnchor),
            visualEffectView.trailingAnchor.constraint(equalTo: trailingAnchor),
            visualEffectView.topAnchor.constraint(equalTo: topAnchor),
            visualEffectView.bottomAnchor.constraint(equalTo: bottomAnchor),

            titleLabel.leadingAnchor.constraint(equalTo: visualEffectView.contentView.leadingAnchor, constant: 20),
            titleLabel.trailingAnchor.constraint(equalTo: visualEffectView.contentView.trailingAnchor, constant: -20),
            titleLabel.topAnchor.constraint(equalTo: visualEffectView.contentView.topAnchor, constant: 20),

            subtitleLabel.leadingAnchor.constraint(equalTo: visualEffectView.contentView.leadingAnchor, constant: 20),
            subtitleLabel.trailingAnchor.constraint(equalTo: visualEffectView.contentView.trailingAnchor, constant: -20),
            subtitleLabel.topAnchor.constraint(equalTo: titleLabel.bottomAnchor, constant: 8),
            subtitleLabel.bottomAnchor.constraint(lessThanOrEqualTo: visualEffectView.contentView.bottomAnchor, constant: -20)
        ])
    }

    required init?(coder: NSCoder) {
        nil
    }
}

@available(iOS 26.0, *)
struct GlassAction: Identifiable {
    let id: String
    let title: String
    let systemImage: String
}
```

A Liquid Glass effektus SwiftUI-ban elsősorban a `glassEffect(_:in:)` modifierrel használható, és Apple szerint a rendszer standard komponenseivel vagy erre a modifierre épített egyedi nézetekkel lehet a legkevesebb kóddal jó eredményt elérni.  Ha több glass elemnek egy közös, összeolvadó viselkedést szeretnél, akkor ezeket `GlassEffectContainer` környezetbe kell tenni, mert ez koordinálja a formák közös renderelését és az egymásba alakuló átmeneteket.[1][2][3]
## Alap használat
A legegyszerűbb megoldás az, hogy egy SwiftUI nézetre közvetlenül ráteszed a glass effectet, és megadsz hozzá egy alakzatot, például kapszulát vagy kört. Az Apple dokumentációja szerint a `glassEffect(_:in:)` kifejezetten arra való, hogy egy nézethez Liquid Glass megjelenést adj, és ezt egy alakzathoz kösd.[1]

```swift
import SwiftUI

struct ContentView: View {
    var body: some View {
        ZStack {
            LinearGradient(
                colors: [.blue, .indigo],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
            .ignoresSafeArea()

            Text("Hello")
                .font(.headline)
                .padding(.horizontal, 20)
                .padding(.vertical, 12)
                .glassEffect(.regular, in: .capsule)
        }
    }
}
```

Ez a minta azért működik jól, mert a Liquid Glass vizuálisan akkor érvényesül igazán, ha gazdagabb háttér fölött lebegő felületeken használod, nem pedig mindenhol az egész UI-ban. Az Apple HIG külön is jelzi, hogy a clear Liquid Glass különösen vizuálisan gazdag háttér fölött ajánlott, és a fejlesztői útmutató az egyedi nézeteknél ugyanezt az irányt támogatja.[4][5]
## Interaktív glass
Ha azt szeretnéd, hogy az elem reagáljon az érintésre finom vizuális visszajelzéssel, akkor interaktív változatot használj. Külső példák és az Apple-hez kapcsolódó dokumentációs hivatkozások alapján a `.interactive()` az a kiegészítés, amely érintésre élőbb viselkedést ad a glass elemnek.[6][7]

```swift
import SwiftUI

struct InteractiveGlassView: View {
    var body: some View {
        Button {
        } label: {
            Label("Lejátszás", systemImage: "play.fill")
                .font(.headline)
                .padding(.horizontal, 18)
                .padding(.vertical, 14)
        }
        .glassEffect(.regular.interactive(), in: .capsule)
    }
}
```

Ez akkor hasznos, ha lebegő gombot, mini vezérlősávot vagy kiemelt akciógombot készítesz. Az Apple általános útmutatója szerint a standard komponensek és a minimális, célzott használat a jó irány, ezért ezt inkább fókuszpontokra érdemes tenni, nem minden gombra a képernyőn.[4][2]
## Több elem összekapcsolása
Ha több glass elemed van, és azt szeretnéd, hogy közel kerülve vizuálisan összetartozzanak vagy összeolvadjanak, használd a `GlassEffectContainer`-t. Az Apple dokumentációja szerint minden, a konténeren belüli glass elem egy közös alakzathalmazhoz járul hozzá, ezért a rendszer együtt tudja renderelni őket.[1][3]

```swift
import SwiftUI

struct GroupedGlassView: View {
    var body: some View {
        ZStack {
            LinearGradient(
                colors: [.cyan, .blue, .indigo],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
            .ignoresSafeArea()

            GlassEffectContainer(spacing: 18) {
                HStack(spacing: 18) {
                    Button("Home") {
                    }
                    .padding(.horizontal, 16)
                    .padding(.vertical, 12)
                    .glassEffect(.regular.interactive(), in: .capsule)

                    Button("Search") {
                    }
                    .padding(.horizontal, 16)
                    .padding(.vertical, 12)
                    .glassEffect(.regular.interactive(), in: .capsule)

                    Button("Profile") {
                    }
                    .padding(.horizontal, 16)
                    .padding(.vertical, 12)
                    .glassEffect(.regular.interactive(), in: .capsule)
                }
            }
        }
    }
}
```

Ez a megközelítés különösen jó lebegő toolbarekhez, egyedi tab barhoz vagy gyorsművelet-menühöz. Apple szerint a `GlassEffectContainer` pont arra való, hogy a `glassEffect(_:in:)` modifierrel ellátott nézetek egy közös, összehangolt glass rendszerként viselkedjenek.[3][1]
## Egyedi átmenetek
Az összetettebb, folyékony átmenetekhez a glass elemeket azonosítóval is össze lehet kötni. A fejlesztői példák szerint ehhez tipikusan `@Namespace` és `.glassEffectID(_:in:)` tartozik, így a rendszer két állapot között is koherensen tudja kezelni ugyanazt a glass identitást.[6][8]

```swift
import SwiftUI

struct MorphingGlassView: View {
    @Namespace private var glassNamespace
    @State private var expanded = false

    var body: some View {
        ZStack {
            LinearGradient(
                colors: [.black, .blue],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
            .ignoresSafeArea()

            GlassEffectContainer {
                VStack(spacing: 16) {
                    if expanded {
                        HStack(spacing: 12) {
                            actionButton("heart.fill", id: "heart")
                            actionButton("bookmark.fill", id: "bookmark")
                            actionButton("square.and.arrow.up.fill", id: "share")
                        }
                    } else {
                        actionButton("ellipsis", id: "menu")
                    }
                }
            }
        }
        .onTapGesture {
            withAnimation(.spring(response: 0.45, dampingFraction: 0.82)) {
                expanded.toggle()
            }
        }
    }

    @ViewBuilder
    private func actionButton(_ systemImage: String, id: String) -> some View {
        Image(systemName: systemImage)
            .font(.title3)
            .padding(18)
            .glassEffect(.regular.interactive(), in: .circle)
            .glassEffectID(id, in: glassNamespace)
    }
}
```

Ez a fajta megoldás jó akkor, amikor egyetlen lebegő gombból bontasz ki több akciót, vagy egy kompakt vezérlőcsoportot szeretnél kibontani. Az Apple mintái és a kapcsolódó közösségi példák alapján a `GlassEffectContainer` és az azonosítók együtt adják a legfolyékonyabb átmeneti élményt.[3][8][9]
## Tervezési szempontok
A Liquid Glass nem háttér-helyettesítő, hanem hangsúlyos, felső rétegbeli anyagként működik a legjobban. Az Apple kifejezetten azt javasolja, hogy inkább standard komponensekre és célzott egyedi elemekre építs, és csökkentsd a saját, nehéz hátterek használatát ott, ahol a rendszer anyagai már megadják a kívánt vizuális mélységet.[4][2]

Gyakorlatban ez azt jelenti, hogy floating gombokhoz, alsó vezérlősávhoz, lebegő menühöz, badge-ekhez és kiemelt akcióelemekhez ideális, de teljes képernyős panelekre vagy sűrű űrlapokra általában nem ez a legjobb választás. Az Apple anyag-útmutatója szerint a glass különösen erős akkor, ha vizuális kontrasztban jelenik meg a mögötte lévő tartalommal.[2][5]

